From adad2da9769a3fd91253da6af39452218ba8fa4c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 03:03:28 +0100
Subject: [PATCH] shell: expose the launcher's global shortcut to QML

Launcher settings want to show the shortcuts of the shell's own Activate
Application Launcher action. Add a property with them as display text,
updated whenever KGlobalAccel reports a change to the action's shortcut.

BUG: 510769
---
 shell/shellcorona.cpp | 17 +++++++++++++++++
 shell/shellcorona.h   |  7 +++++++
 2 files changed, 24 insertions(+)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..b62eca87f8 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -200,6 +200,11 @@ void ShellCorona::init()
     activateLauncherAction->setText(i18n("Activate Application Launcher"));
     KGlobalAccel::self()->setGlobalShortcut(activateLauncherAction,
                                             QList<QKeySequence>() << QKeySequence(Qt::Key_Meta) << QKeySequence(Qt::AltModifier | Qt::Key_F1));
+    connect(KGlobalAccel::self(), &KGlobalAccel::globalShortcutChanged, this, [this, activateLauncherAction](QAction *action) {
+        if (action == activateLauncherAction) {
+            Q_EMIT launcherShortcutsChanged();
+        }
+    });

     // Activity stuff
     auto *activityAction = new QAction(this);
@@ -2315,6 +2320,18 @@ PanelView *ShellCorona::panelBeingConfigured() const
     return nullptr;
 }

+QStringList ShellCorona::launcherShortcuts() const
+{
+    QStringList shortcuts;
+    const QList<QKeySequence> keys = KGlobalAccel::self()->shortcut(action(u"activate application launcher"_s));
+    for (const QKeySequence &key : keys) {
+        if (!key.isEmpty()) {
+            shortcuts << key.toString(QKeySequence::NativeText);
+        }
+    }
+    return shortcuts;
+}
+
 bool ShellCorona::enteredEditModeViaDesktop()
 {
     for (DesktopView *desktop : m_desktopViewForScreen) {
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..c734a48799 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -56,6 +56,7 @@ class ShellCorona : public Plasma::Corona, QDBusContext
     Q_PROPERTY(QString shell READ shell NOTIFY shellChanged)
     Q_PROPERTY(uint numScreens READ numScreens)
     Q_PROPERTY(PanelView *panelBeingConfigured READ panelBeingConfigured NOTIFY panelBeingConfiguredChanged)
+    Q_PROPERTY(QStringList launcherShortcuts READ launcherShortcuts NOTIFY launcherShortcutsChanged)
     Q_CLASSINFO("D-Bus Interface", "org.kde.PlasmaShell")

 public:
@@ -137,6 +138,11 @@ public:

     PanelView *panelBeingConfigured() const;

+    /**
+     * The shortcuts of the global "Activate Application Launcher" action, as text
+     */
+    QStringList launcherShortcuts() const;
+
     Q_INVOKABLE bool enteredEditModeViaDesktop();

     Q_INVOKABLE bool isScreenUiReady(uint screen);
@@ -170,6 +176,7 @@ Q_SIGNALS:

     void wallpaperChanged(uint screenNum);
     void panelBeingConfiguredChanged();
+    void launcherShortcutsChanged();
     // Emitted when the shell property is set, but before the new shell is loaded
     void shellAboutToChange(const QString &shell);
     // Emitted after the new shell has loaded
